css:
/* The handoff's compact contact band: a 640px stack, 20px between its three
   parts, and one dark button. It closes the story, team and editorial pages. */
[data-bz-section="cta-compact"] > .bz-section { padding-block: 80px }
[data-bz-section="cta-compact"] > .bz-section > .bz-container { max-width: calc(640px + 2 * var(--container-pad)) }
[data-bz-section="cta-compact"] .bz-block { padding-block: 0 }
[data-bz-section="cta-compact"] .bz-block + .bz-block { padding-block-start: 18px }
[data-bz-section="cta-compact"] .bz-eyebrow { color: var(--chrome-meta); text-align: center; margin-bottom: 18px }
[data-bz-section="cta-compact"] h2 { font-size: 28px; line-height: 1.6; color: #fff; margin: 0 }
[data-bz-section="cta-compact"] [data-bz-node="ctc-body"] .bz-text { margin-inline: auto; max-width: 640px }
[data-bz-section="cta-compact"] [data-bz-node="ctc-body"] p { color: var(--chrome-body); font-size: 15px; line-height: 1.7; margin: 0 }
[data-bz-section="cta-compact"] .bz-btns { justify-content: center; margin-block: 0; gap: 14px }
[data-bz-section="cta-compact"] .bz-btn { min-height: 46px; padding: 0 16px }
[data-bz-section="cta-compact"] .bz-btn--primary { background: var(--accent); color: #fff }
[data-bz-section="cta-compact"] .bz-btn--primary:hover { background: var(--accent-dark) }
[data-bz-section="cta-compact"] .bz-btn--secondary { background: transparent; color: #fff; border-color: #fff }
[data-bz-section="cta-compact"] .bz-section--bg-accent [data-bz-node="ctc-body"] p { color: #FFD9D5 }
@media (max-width: 640px) { [data-bz-section="cta-compact"] > .bz-section { padding-block: 56px } }
[data-bz-section="cta-compact"] [data-bz-node="ctc-note"] p { color: var(--chrome-meta); font-size: 13px; line-height: 1.6; margin: 0 }
